#include <stdio.h>
#include <stdlib.h>

static int bounded_rand(unsigned int bound, unsigned int *result)
{
    unsigned long range;
    unsigned long limit;
    unsigned long value;

    if (bound == 0U || result == NULL) {
        return 0;
    }
    range = (unsigned long)RAND_MAX + 1UL;
    if ((unsigned long)bound > range) {
        return 0;
    }
    limit = range - (range % (unsigned long)bound);
    do {
        value = (unsigned long)rand();
    } while (value >= limit);
    *result = (unsigned int)(value % (unsigned long)bound);
    return 1;
}

int main(void)
{
    unsigned int value;
    srand(1234U);
    if (!bounded_rand(10U, &value)) {
        return 1;
    }
    printf("value=%u\n", value);
    return 0;
}
